def _enforce_cognito_token_key(is_dev):
    """S2: Cognito açıkken prod'da COGNITO_TOKEN_ENC_KEY zorunlu.

    session_store, anahtar yokken SECRET_KEY'den türetmeye düşüyordu — SECRET_KEY
    (oturumları da imzalar) sızarsa DB'deki tüm Cognito access/refresh token'ları
    çözülebilirdi. Wearable tarafı (crypto.py) özel anahtarı zaten zorunlu kılar;
    aynı kuralı burada BOOT'ta uygula: _get_fernet tembel olduğundan kullanım-anı
    hatası deploy gate'ten kaçar, boot hatasıysa health gate'te rollback tetikler.
    """
    if is_dev or not COGNITO_ENABLED:
        return
    if not COGNITO_TOKEN_ENC_KEY:
        raise RuntimeError(
            "COGNITO_TOKEN_ENC_KEY must be set when Cognito is enabled outside "
            "debug/dev. Generate one with: python -c \"from cryptography.fernet "
            "import Fernet; print(Fernet.generate_key().decode())\"")


def _enforce_fatsecret_tls(app):
    from urllib.parse import urlparse as _urlparse
    if not FATSECRET_BASE_URL:
        app.logger.warning(
            "FATSECRET_BASE_URL ayarlı değil — FatSecret entegrasyonu çalışmaz. "
            "https:// bir endpoint'e işaret ettir.")
        return
    p = _urlparse(FATSECRET_BASE_URL)
    host = (p.hostname or "").lower()
    is_local = host in ("localhost", "127.0.0.1", "::1")
    if p.scheme == "https" or is_local:
        return
    # Düz metin HTTP + loopback dışı: debug olsun olmasın engelle. Token Authorization
    # header'ında gidiyor; cleartext kabul edilemez. Lokal http proxy'e karşı test
    # için bilinçli FATSECRET_ALLOW_INSECURE=1 escape-hatch'i gerekir.
    if os.environ.get("FATSECRET_ALLOW_INSECURE") == "1":
        app.logger.warning(
            "FATSECRET_BASE_URL düz metin http (%s) — FATSECRET_ALLOW_INSECURE=1 ile "
            "izin verildi. Bearer token tel üzerinde açıkta; yalnızca lokal test için.",
            FATSECRET_BASE_URL,
        )
        return
    raise RuntimeError(
        "FATSECRET_BASE_URL must use https:// — the FatSecret OAuth token is sent "
        "in the Authorization header and would otherwise travel in cleartext. Point "
        "FATSECRET_BASE_URL at an https:// endpoint (terminate TLS in front of the "
        "proxy), or set FATSECRET_ALLOW_INSECURE=1 for local http testing."
    )


def configure_app(app):
    # Tek güvenilir reverse proxy (host nginx) arkasında: X-Forwarded-For/-Proto'nun
    # yanı sıra -Host ve -Port'a da güven; url_for(_external)/redirect'ler ve secure
    # cookie kararları için doğru host/şema/port'u Flask'ın görmesini sağlar.
    app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1, x_host=1, x_port=1)
    # Dev/debug bayrağını configure_app içinde TEK kez değerlendir ve hem SECRET_KEY
    # hem secure-cookie kararlarında AYNI değeri kullan (M9). Eskiden cookie kararı
    # modül-yükü sabiti _IS_DEV'e, SECRET_KEY mantığı ise çağrı-anı env okumasına
    # bakıyordu; bu asimetri, FLASK_ENV=development ile SECRET_KEY zorunluluğunu
    # aşan bir kurulumda Secure cookie'leri de sessizce kapatabilirdi.
    _is_dev = (os.environ.get("FLASK_DEBUG") == "1"
               or os.environ.get("FLASK_ENV") == "development")
    app.config["FITX_IS_DEV"] = _is_dev
    _LOG_LEVEL = os.environ.get("LOG_LEVEL", "INFO").upper()
    _gunicorn_logger = logging.getLogger("gunicorn.error")
    if _gunicorn_logger.handlers:
        app.logger.handlers = _gunicorn_logger.handlers
        app.logger.setLevel(_gunicorn_logger.level or getattr(logging, _LOG_LEVEL, logging.INFO))
    else:
        logging.basicConfig(level=getattr(logging, _LOG_LEVEL, logging.INFO))
        app.logger.setLevel(getattr(logging, _LOG_LEVEL, logging.INFO))
    database_url = os.environ.get("DATABASE_URL")
    if not database_url:
        # Prod'da DATABASE_URL eksikse hızlı patla: aksi halde efemeral SQLite'a
        # düşülür ve redeploy'da veri sessizce kaybolurdu (3.5). Dev'de SQLite tamam.
        if not _is_dev:
            raise RuntimeError(
                "DATABASE_URL is required in production. Set it (PostgreSQL), "
                "or run in dev mode (FLASK_DEBUG=1 / FLASK_ENV=development) to "
                "fall back to local SQLite.")
        database_url = "sqlite:///chatbot.db"
    if database_url.startswith("postgres://"):
        database_url = database_url.replace("postgres://", "postgresql://", 1)
    app.config["SQLALCHEMY_DATABASE_URI"] = database_url
    app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False
    # A3: DB artık dış RDS — havuzdaki bağlantılar boşta kalınca (gece/az trafik)
    # RDS/NAT idle-timeout'u veya failover onları sessizce koparır; ilk istekler
    # "server closed the connection unexpectedly" 500'leri yer, /health'in
    # SELECT 1'i bile flap edebilirdi. pre_ping ölü bağlantıyı kullanmadan önce
    # yakalar; recycle (< RDS idle timeout) bağlantıları proaktif tazeler.
    # SQLite'ta (lokal/test) gereksiz — yalnızca Postgres'te uygula.
    if database_url.startswith("postgresql"):
        app.config["SQLALCHEMY_ENGINE_OPTIONS"] = {
            "pool_pre_ping": True,
            "pool_recycle": int(os.environ.get("DB_POOL_RECYCLE_SECONDS", "280")),
        }
    app.config["AI_PLAN_QUOTA_ENABLED"] = AI_PLAN_QUOTA_ENABLED
    app.config["AI_CHAT_QUOTA_ENABLED"] = AI_CHAT_QUOTA_ENABLED
    app.config["AI_MEMORY_ENABLED"] = AI_MEMORY_ENABLED
    app.config["LOGIN_FAIL_CLOSED"] = LOGIN_FAIL_CLOSED
    app.config["BEDROCK_ENABLED"] = BEDROCK_ENABLED
    _secret_key = os.environ.get("SECRET_KEY")
    if not _secret_key:
        # Allow boot without SECRET_KEY only in explicit debug mode, and generate
        # a per-process random key so dev sessions still cannot be forged from
        # a known constant. Sessions invalidate on restart, which is fine in dev.
        if _is_dev:
            import secrets as _secrets
            _secret_key = _secrets.token_urlsafe(32)
            app.logger.warning("SECRET_KEY not set; using ephemeral dev key (sessions invalidate on restart).")
        else:
            raise RuntimeError(
                "SECRET_KEY environment variable must be set. "
                "Set FLASK_DEBUG=1 to allow an ephemeral key for local development."
            )
    app.config["SECRET_KEY"] = _secret_key
    _enforce_fatsecret_tls(app)
    _enforce_cognito_token_key(_is_dev)
    # A6: prod'da sessizce yanlış moda düşen bayrakları GÖRÜNÜR yap. Bunlar
    # boot'u durdurmaz (meşru geçici kullanımlar olabilir) ama error seviyesinde
    # loglanır ki "her şey yeşil ama yanlış" durumu deploy çıktısında yakalansın.
    if not _is_dev:
        if "BEDROCK_ENABLED" not in os.environ:
            app.logger.error(
                "BEDROCK_ENABLED ayarlı değil (vars. 0) — birincil ağır AI yolu "
                "(Bedrock/Sonnet) KAPALI, koç/menü/plan sessizce OpenAI %s'e düşer. "
                "Prod .env'de BEDROCK_ENABLED=1 bekleniyor; bilinçliyse =0 yazın.",
                OPENAI_MODEL)
        if not FATSECRET_BASE_URL:
            app.logger.error(
                "FATSECRET_BASE_URL ayarlı değil — besin aramaları sessizce "
                "başarısız olur (menü/koç/diary makro çözümü LLM tahminine düşer).")
        if os.environ.get("FITX_SKIP_DB_INIT") == "1":
            app.logger.error(
                "FITX_SKIP_DB_INIT=1 prod'da AKTİF — create_all/migration/seed "
                "atlanıyor. Bu bayrak yalnızca CI/migration komutları içindir.")
    app.config["SESSION_COOKIE_HTTPONLY"] = True
    app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
    app.config["SESSION_COOKIE_SECURE"] = not _is_dev
    app.config["REMEMBER_COOKIE_HTTPONLY"] = True
    app.config["REMEMBER_COOKIE_SAMESITE"] = "Lax"
    app.config["REMEMBER_COOKIE_SECURE"] = not _is_dev
    # Kalıcı oturum ömrünü açıkça sınırla — Flask varsayılanı 31 gün. Env ile
    # ayarlanabilir (gün), aksi halde 7 gün. Çerez/oturum maruziyetini kısaltır.
    _session_days = int(os.environ.get("PERMANENT_SESSION_LIFETIME_DAYS", "7"))
    app.config["PERMANENT_SESSION_LIFETIME"] = timedelta(days=_session_days)
